import 'dart:convert';import 'package:flutter/material.dart';import 'package:file_picker/file_picker.dart';import 'package:share_plus/share_plus.dart';import '../../data/local_database.dart';
class BackupScreen extends StatelessWidget{const BackupScreen({super.key});
static const tables=['users','store_settings','products','invoices','invoice_items','returns','return_items','cash_transactions','network_transactions','expenses','stock_movements','app_settings'];
Future<void> export(BuildContext c)async{final db=await LocalDatabase.instance.database;final data=<String,Object?>{'format':'ARSAD_BACKUP','version':1,'created_at':DateTime.now().toIso8601String(),'tables':{}};final map=data['tables'] as Map<String,Object?>;for(final t in tables){map[t]=await db.query(t);}final bytes=utf8.encode(const JsonEncoder.withIndent('  ').convert(data));await Share.shareXFiles([XFile.fromData(bytes,mimeType:'application/json',name:'arsad-backup.json')]);}
Future<void> restore(BuildContext c)async{final picked=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json'],withData:true);if(picked==null)return;try{final raw=utf8.decode(picked.files.single.bytes!);final data=jsonDecode(raw) as Map<String,dynamic>;if(data['format']!='ARSAD_BACKUP'||data['version']!=1)throw Exception('صيغة النسخة غير معروفة');final tablesMap=data['tables'] as Map<String,dynamic>;final db=await LocalDatabase.instance.database;await db.transaction((txn)async{for(final t in tables.reversed){await txn.delete(t);}for(final t in tables){final rows=(tablesMap[t] as List<dynamic>? ?? []);for(final row in rows){await txn.insert(t,Map<String,Object?>.from(row as Map));}}});if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('تمت الاستعادة')));}catch(e){if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('فشلت الاستعادة: $e')));}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('النسخ الاحتياطي')),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('احفظ نسخة JSON في مكان آمن. الاستعادة تستبدل بيانات التطبيق الحالية.'),const SizedBox(height:16),FilledButton.icon(onPressed:()=>export(c),icon:const Icon(Icons.save_alt),label:const Text('تصدير نسخة احتياطية')),OutlinedButton.icon(onPressed:()async{final ok=await showDialog<bool>(context:c,builder:(d)=>AlertDialog(title:const Text('تأكيد الاستعادة'),content:const Text('سيتم استبدال البيانات الحالية. هل تريد المتابعة؟'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('متابعة'))]));if(ok==true)await restore(c);},icon:const Icon(Icons.restore),label:const Text('استعادة نسخة'))]));}
